#include <cstdint>
#include <deque>
#include <functional>
#include <map>
#include <memory>
#include <set>
#include <utility>

using HWND = int;
using UINT = std::uint32_t;
using WPARAM = std::uint64_t;
using LPARAM = std::int64_t;
using LRESULT = std::int64_t;

constexpr UINT WM_DESTROY = 0x0002, WM_PAINT = 0x000F, WM_CLOSE = 0x0010, WM_QUIT = 0x0012, WM_TIMER = 0x0113, WM_APP = 0x8000;
struct MSG { HWND hwnd; UINT message; WPARAM wParam; LPARAM lParam; };

class Desktop
{
public:
    using Proc = std::function<LRESULT(Desktop&, HWND, UINT, WPARAM, LPARAM)>;

    HWND createWindow(Proc proc)
    {
        const HWND h{ m_next++ };
        m_windows[h] = std::make_shared<Proc>(std::move(proc));
        return h;
    }

    bool isWindow(HWND hwnd) const { return m_windows.count(hwnd) != 0; }

    bool destroyWindow(HWND hwnd)
    {
        if (!isWindow(hwnd)) return false;
        sendMessage(hwnd, WM_DESTROY, 0, 0);
        m_windows.erase(hwnd);
        m_invalid.erase(hwnd);
        for (auto it{ m_timers.begin() }; it != m_timers.end();) it = it->first.first == hwnd ? m_timers.erase(it) : std::next(it);
        for (auto it{ m_posted.begin() }; it != m_posted.end();) it = it->hwnd == hwnd ? m_posted.erase(it) : std::next(it);
        return true;
    }

    LRESULT sendMessage(HWND hwnd, UINT msg, WPARAM w, LPARAM l)
    {
        auto it{ m_windows.find(hwnd) };
        if (it == m_windows.end()) return 0;
        const std::shared_ptr<Proc> proc{ it->second };      // keeps the procedure alive even if the window is destroyed meanwhile
        return (*proc)(*this, hwnd, msg, w, l);
    }

    bool postMessage(HWND hwnd, UINT msg, WPARAM w, LPARAM l)
    {
        if (!isWindow(hwnd)) return false;
        m_posted.push_back({ hwnd, msg, w, l });
        return true;
    }

    void postQuitMessage(int code) { m_quit = true; m_quitCode = code; }
    void invalidate(HWND hwnd) { if (isWindow(hwnd)) m_invalid.insert(hwnd); }
    void validate(HWND hwnd) { m_invalid.erase(hwnd); }

    void setTimer(HWND hwnd, UINT id, int periodMs)
    {
        if (isWindow(hwnd)) m_timers[{ hwnd, id }] = { periodMs, m_now + periodMs };
    }

    void killTimer(HWND hwnd, UINT id) { m_timers.erase({ hwnd, id }); }
    void advance(int ms) { m_now += ms; }

    bool peekMessage(MSG& out)
    {
        if (!m_posted.empty()) { out = m_posted.front(); m_posted.pop_front(); return true; }
        if (m_quit) { m_quit = false; out = { 0, WM_QUIT, static_cast<WPARAM>(m_quitCode), 0 }; return true; }
        if (!m_invalid.empty()) { out = { *m_invalid.begin(), WM_PAINT, 0, 0 }; return true; }
        auto best{ m_timers.end() };
        for (auto it{ m_timers.begin() }; it != m_timers.end(); ++it)
            if (it->second.next <= m_now && (best == m_timers.end() || it->second.next < best->second.next)) best = it;
        if (best != m_timers.end())
        {
            best->second.next = m_now + best->second.period;
            out = { best->first.first, WM_TIMER, best->first.second, 0 };
            return true;
        }
        return false;
    }

    int run()
    {
        MSG msg{};
        while (peekMessage(msg))
        {
            if (msg.message == WM_QUIT) return static_cast<int>(msg.wParam);
            sendMessage(msg.hwnd, msg.message, msg.wParam, msg.lParam);
        }
        return -1;
    }

    LRESULT defWindowProc(HWND hwnd, UINT msg, WPARAM, LPARAM)
    {
        if (msg == WM_CLOSE) destroyWindow(hwnd);
        else if (msg == WM_PAINT) validate(hwnd);
        return 0;
    }

private:
    struct Timer { int period; long long next; };
    std::map<HWND, std::shared_ptr<Proc>> m_windows;
    std::deque<MSG> m_posted;
    std::set<HWND> m_invalid;
    std::map<std::pair<HWND, UINT>, Timer> m_timers;
    HWND m_next{ 1 };
    bool m_quit{ false };
    int m_quitCode{ 0 };
    long long m_now{ 0 };
};

unitTests:
#include <string>
#include <vector>
using Log = std::vector<std::string>;
Desktop::Proc logger(Log& log) { return [&log](Desktop& d, HWND h, UINT m, WPARAM w, LPARAM l) -> LRESULT { log.push_back(std::to_string(h) + ":" + std::to_string(m) + ":" + std::to_string(w)); return d.defWindowProc(h, m, w, l); }; }
TEST("windows and sending") {
    Desktop d; Log log;
    const HWND a = d.createWindow([](Desktop&, HWND, UINT m, WPARAM w, LPARAM) -> LRESULT { return m == WM_APP ? static_cast<LRESULT>(w * 2) : 0; });
    const HWND b = d.createWindow(logger(log));
    CHECK_EQ(a, 1); CHECK_EQ(b, 2); CHECK_EQ(d.sendMessage(a, WM_APP, 21, 0), LRESULT{ 42 }); CHECK_EQ(d.sendMessage(9, WM_APP, 1, 0), LRESULT{ 0 }); CHECK(!d.postMessage(9, WM_APP, 0, 0));
}
TEST("the order of messages") {
    Desktop d; Log log; const HWND a = d.createWindow(logger(log));
    d.invalidate(a); d.postQuitMessage(3); d.postMessage(a, WM_APP, 1, 0); d.postMessage(a, WM_APP, 2, 0);
    MSG m{};
    CHECK(d.peekMessage(m)); CHECK_EQ(m.wParam, WPARAM{ 1 }); CHECK(d.peekMessage(m)); CHECK_EQ(m.wParam, WPARAM{ 2 });
    CHECK(d.peekMessage(m)); CHECK_EQ(m.message, WM_QUIT); CHECK_EQ(m.wParam, WPARAM{ 3 });
    CHECK(d.peekMessage(m)); CHECK_EQ(m.message, WM_PAINT); CHECK(d.peekMessage(m)); CHECK_EQ(m.message, WM_PAINT);
    d.validate(a); CHECK(!d.peekMessage(m));
}
TEST("paints combine and come last") {
    Desktop d; Log log; const HWND a = d.createWindow(logger(log)), b = d.createWindow(logger(log));
    d.invalidate(b); d.invalidate(a); d.invalidate(b);
    MSG m{}; d.peekMessage(m); CHECK_EQ(m.hwnd, a); d.validate(a); d.peekMessage(m); CHECK_EQ(m.hwnd, b); d.validate(b); CHECK(!d.peekMessage(m));
}
TEST("timers") {
    Desktop d; Log log; const HWND a = d.createWindow(logger(log)); MSG m{};
    d.setTimer(a, 7, 100); d.advance(50); CHECK(!d.peekMessage(m));
    d.advance(50); CHECK(d.peekMessage(m)); CHECK_EQ(m.message, WM_TIMER); CHECK_EQ(m.wParam, WPARAM{ 7 }); CHECK(!d.peekMessage(m));
    d.advance(350); CHECK(d.peekMessage(m)); CHECK(!d.peekMessage(m)); d.advance(99); CHECK(!d.peekMessage(m)); d.advance(1); CHECK(d.peekMessage(m));
    d.setTimer(a, 1, 30); d.setTimer(a, 2, 10); d.advance(40); d.peekMessage(m); CHECK_EQ(m.wParam, WPARAM{ 2 }); d.peekMessage(m); CHECK_EQ(m.wParam, WPARAM{ 1 });
    d.killTimer(a, 1); d.killTimer(a, 2); d.killTimer(a, 7); d.advance(1000); CHECK(!d.peekMessage(m));
}
TEST("the message loop") {
    Desktop d; Log log;
    const HWND a = d.createWindow([&log](Desktop& dt, HWND h, UINT m, WPARAM w, LPARAM l) -> LRESULT {
        log.push_back(std::to_string(m));
        if (m == WM_APP) dt.postMessage(h, WM_APP + 1, 0, 0);
        if (m == WM_APP + 1) dt.postQuitMessage(42);
        return dt.defWindowProc(h, m, w, l);
    });
    d.invalidate(a); d.postMessage(a, WM_APP, 0, 0);
    CHECK_EQ(d.run(), 42); CHECK_EQ(log, (Log{ "32768", "32769" })); CHECK_EQ(d.run(), -1); CHECK_EQ(log.back(), std::string("15"));
}
TEST("closing a window") {
    Desktop d; Log log;
    const HWND a = d.createWindow([&log](Desktop& dt, HWND h, UINT m, WPARAM w, LPARAM l) -> LRESULT {
        if (m == WM_CLOSE) log.push_back("close");
        if (m == WM_DESTROY) { log.push_back("destroy"); dt.postQuitMessage(0); }
        return dt.defWindowProc(h, m, w, l);
    });
    d.setTimer(a, 1, 10); d.invalidate(a); d.postMessage(a, WM_CLOSE, 0, 0); d.postMessage(a, WM_APP, 0, 0);
    CHECK_EQ(d.run(), 0); CHECK(!d.isWindow(a)); CHECK_EQ(log, (Log{ "close", "destroy" }));
    d.advance(100); MSG m{}; CHECK(!d.peekMessage(m)); CHECK(!d.destroyWindow(a));
}

